"""go-bootstrap-runs-on-provided-al2023-arm64."""

from __future__ import annotations

import base64
import hashlib
import io
import json
import lzma
import time
import zipfile

from botocore.exceptions import ClientError

from behavioral_harness import tags


CHECK = 'go-bootstrap-runs-on-provided-al2023-arm64'
GROUP = 'data-plane'
SERVICES = ['lambda']

ARCH = 'arm64'
GOARCH = 'arm64'
HANDLER = 'pkg/cmd.Run'

# A self-contained Go program, built once per architecture (CGO disabled, standard library
# only: net, bufio, os, runtime, strconv, strings, time, io, encoding/base64). It never
# touches any AWS SDK; it only speaks the Lambda Runtime API over plain TCP. The binary is
# embedded below as lzma+base64 with its SHA-256 asserted, so the check needs no Go toolchain
# at run time.
GO_SOURCE = r"""
package main

import (
	"bufio"
	"encoding/base64"
	"io"
	"net"
	"os"
	"runtime"
	"strconv"
	"strings"
	"time"
)

func dial() net.Conn {
	api := os.Getenv("AWS_LAMBDA_RUNTIME_API")
	conn, err := net.Dial("tcp", api)
	if err != nil {
		os.Exit(1)
	}
	return conn
}

func readResponse(r *bufio.Reader) (status string, headers map[string]string, body []byte) {
	statusLine, _ := r.ReadString('\n')
	status = strings.TrimSpace(statusLine)
	headers = map[string]string{}
	for {
		line, _ := r.ReadString('\n')
		line = strings.TrimRight(line, "\r\n")
		if line == "" {
			break
		}
		if idx := strings.Index(line, ":"); idx >= 0 {
			k := strings.ToLower(strings.TrimSpace(line[:idx]))
			v := strings.TrimSpace(line[idx+1:])
			headers[k] = v
		}
	}
	n, _ := strconv.Atoi(headers["content-length"])
	body = make([]byte, n)
	io.ReadFull(r, body)
	return
}

func doRequest(method, path string, reqBody []byte) (map[string]string, []byte) {
	conn := dial()
	defer conn.Close()
	api := os.Getenv("AWS_LAMBDA_RUNTIME_API")
	var b strings.Builder
	b.WriteString(method + " " + path + " HTTP/1.1\r\n")
	b.WriteString("Host: " + api + "\r\n")
	b.WriteString("Connection: close\r\n")
	if reqBody != nil {
		b.WriteString("Content-Length: " + strconv.Itoa(len(reqBody)) + "\r\n")
	}
	b.WriteString("\r\n")
	conn.Write([]byte(b.String()))
	if reqBody != nil {
		conn.Write(reqBody)
	}
	r := bufio.NewReader(conn)
	_, headers, body := readResponse(r)
	return headers, body
}

func bootID() string {
	return strconv.FormatInt(time.Now().UnixNano(), 36) + "-" + strconv.Itoa(os.Getpid())
}

func main() {
	handler := os.Getenv("_HANDLER")
	boot := bootID()
	pid := strconv.Itoa(os.Getpid())
	n := 0
	for {
		n++
		headers, event := doRequest("GET", "/2018-06-01/runtime/invocation/next", nil)
		reqID := headers["lambda-runtime-aws-request-id"]

		var out strings.Builder
		out.WriteString("{")
		out.WriteString(`"handler":"` + handler + `",`)
		out.WriteString(`"goarch":"` + runtime.GOARCH + `",`)
		out.WriteString(`"goos":"` + runtime.GOOS + `",`)
		out.WriteString(`"boot":"` + boot + `",`)
		out.WriteString(`"pid":"` + pid + `",`)
		out.WriteString(`"invocation":` + strconv.Itoa(n) + `,`)
		out.WriteString(`"request_id":"` + reqID + `",`)
		out.WriteString(`"payload_b64":"` + base64.StdEncoding.EncodeToString(event) + `"`)
		out.WriteString("}")
		respBody := []byte(out.String())

		doRequest("POST", "/2018-06-01/runtime/invocation/"+reqID+"/response", respBody)
	}
}
"""


_SHA256 = "cd526a47ee65b61613e409f259c05b5f0eb6cf9c90bf4a7dd43d61d74f3b83e4"

_B64 = (  # @@GENERATED@@ arm64
    ""
)


def _binary():
    """The lzma+base64-embedded Go ``bootstrap`` binary, SHA-256 verified."""
    raw = lzma.decompress(base64.b64decode(_B64))
    got = hashlib.sha256(raw).hexdigest()
    assert got == _SHA256, (
        f"embedded {ARCH} binary is sha256 {got!r}, pinned {_SHA256!r} — the "
        f"bytes under test are not the bytes this check was verified against"
    )
    return raw


def _make_zip(name, data, mode=0o100755):
    """A one-entry deployment zip with an explicit unix mode."""
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        info = zipfile.ZipInfo(name, date_time=(1980, 1, 1, 0, 0, 0))
        info.create_system = 3
        info.external_attr = mode << 16
        zf.writestr(info, data)
    return buf.getvalue()


def _teardown(undo, *not_found: str):
    """A cleanup running ``undo()`` where a failed delete raises; only ``not_found`` means gone."""

    def run_undo():
        try:
            undo()
        except ClientError as exc:
            if exc.response["Error"]["Code"] in not_found:
                return
            raise

    return run_undo


def _reap_log_groups(logs, names, *, reads=3, interval_s=4.0, budget_s=60.0):
    """Delete every group in ``names`` until ``reads`` consecutive rounds find all absent."""
    deadline = time.monotonic() + budget_s
    absent = 0
    while absent < reads:
        present = [
            name for name in names
            if any(g["logGroupName"] == name
                   for g in logs.describe_log_groups(logGroupNamePrefix=name)["logGroups"])
        ]
        for name in present:
            try:
                logs.delete_log_group(logGroupName=name)
            except ClientError as exc:
                if exc.response["Error"]["Code"] != "ResourceNotFoundException":
                    raise
        absent = 0 if present else absent + 1
        if absent < reads:
            if time.monotonic() > deadline:
                raise AssertionError(f"log groups {present!r} still present after {budget_s}s")
            time.sleep(interval_s)


_ROLE_NOT_READY = "The role defined for the function cannot be assumed by Lambda."
_BASIC_EXEC = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"


def _execution_role(ctx):
    """An execution role this check creates and deletes."""
    iam = ctx.client("iam")
    name = ctx.unique_name("sim2real-behav-gorole-")
    trust = json.dumps({
        "Version": "2012-10-17",
        "Statement": [{
            "Effect": "Allow",
            "Principal": {"Service": "lambda.amazonaws.com"},
            "Action": "sts:AssumeRole",
        }],
    })
    arn = iam.create_role(RoleName=name, AssumeRolePolicyDocument=trust,
                          Tags=[{"Key": "sim2real", "Value": CHECK}])["Role"]["Arn"]
    ctx.on_cleanup(_teardown(lambda: iam.delete_role(RoleName=name), "NoSuchEntity"))
    iam.attach_role_policy(RoleName=name, PolicyArn=_BASIC_EXEC)
    ctx.on_cleanup(_teardown(
        lambda: iam.detach_role_policy(RoleName=name, PolicyArn=_BASIC_EXEC), "NoSuchEntity"))
    return arn


def _create_function(lam, **kwargs):
    """CreateFunction, retried while a freshly created execution role is still propagating."""
    deadline = time.monotonic() + 90
    while True:
        try:
            return lam.create_function(**kwargs)
        except ClientError as exc:
            err = exc.response.get("Error", {})
            not_ready = (err.get("Code") == "InvalidParameterValueException"
                         and err.get("Message") == _ROLE_NOT_READY)
            if not not_ready or time.monotonic() > deadline:
                raise
            time.sleep(3)


def _wait_active(lam, fn, timeout_s=180):
    deadline = time.monotonic() + timeout_s
    while time.monotonic() < deadline:
        cfg = lam.get_function_configuration(FunctionName=fn)
        if cfg["State"] == "Failed":
            raise AssertionError(f"{fn} entered State=Failed: {cfg.get('StateReason')!r}")
        if cfg["State"] == "Active":
            return cfg
        time.sleep(1)
    raise AssertionError(f"{fn} did not reach State=Active within {timeout_s}s")


def _invoke(lam, fn, payload):
    resp = lam.invoke(FunctionName=fn, Payload=payload, LogType="Tail")
    raw = resp["Payload"].read()
    assert resp["StatusCode"] == 200, f"{fn}: StatusCode {resp['StatusCode']!r} {raw!r}"
    assert resp.get("FunctionError") is None, (
        f"{fn}: FunctionError={resp.get('FunctionError')!r}, payload {raw!r}"
    )
    return json.loads(raw)


@tags("axis:happy-path", "cap:c3", "concern:data-plane",
      "concern:representation", "dp:api", "plane:data")
def run(ctx) -> None:
    """A statically linked Go binary runs under provided.al2023/arm64, with _HANDLER, GOARCH and
    the invoke payload all matching configuration.

    Reference: https://docs.aws.amazon.com/lambda/latest/dg/runtimes-provided.html
    Reference: https://docs.aws.amazon.com/lambda/latest/dg/golang-handler.html
    Reference: https://docs.aws.amazon.com/lambda/latest/dg/runtimes-api.html
    """
    lam = ctx.client("lambda")
    logs = ctx.client("logs")
    role = _execution_role(ctx)

    binary = _binary()
    zip_bytes = _make_zip("bootstrap", binary)

    name = ctx.unique_name("sim2real-behav-go-al2023-arm64-")
    log_group = f"/aws/lambda/{name}"
    ctx.on_cleanup(lambda: _reap_log_groups(logs, [log_group]))
    _create_function(
        lam, FunctionName=name, Runtime="provided.al2023", Handler=HANDLER,
        Role=role, Code={"ZipFile": zip_bytes}, Architectures=[ARCH],
        MemorySize=512, Timeout=20, Tags={"sim2real": CHECK},
    )
    ctx.on_cleanup(_teardown(
        lambda: lam.delete_function(FunctionName=name), "ResourceNotFoundException"
    ))
    cfg = _wait_active(lam, name)

    assert cfg["Runtime"] == "provided.al2023", (
        f"{name} was created with Runtime='provided.al2023' but reports "
        f"Runtime={cfg['Runtime']!r}"
    )
    assert cfg["Architectures"] == [ARCH], (
        f"{name} was created with Architectures=[{ARCH!r}] but reports "
        f"{cfg['Architectures']!r}"
    )

    bodies = []
    for i in range(2):
        payload_obj = {
            "arch": ARCH, "i": i, "text": "quote\"and\\backslash and emoji 🚀",
        }
        payload = json.dumps(payload_obj, ensure_ascii=False).encode("utf-8")
        body = _invoke(lam, name, payload)
        assert base64.b64decode(body["payload_b64"]) == payload, (
            f"{name}: the invoke payload did not round trip byte-exact through the Go "
            f"bootstrap; sent {payload!r}, got back {base64.b64decode(body['payload_b64'])!r}"
        )
        bodies.append(body)

    first = bodies[0]
    assert first["handler"] == HANDLER, (
        f"{name}: _HANDLER carried {first['handler']!r}, expected the configured Handler "
        f"{HANDLER!r}"
    )
    assert first["goarch"] == GOARCH, (
        f"{name}: the Go binary's own runtime.GOARCH was {first['goarch']!r}, expected "
        f"{GOARCH!r} for Architectures=[{ARCH!r}] — the binary that ran was not "
        f"compiled for this function's architecture"
    )
    assert first["goos"] == "linux", (
        f"{name}: runtime.GOOS was {first['goos']!r}, not 'linux'"
    )
    assert bodies[0]["request_id"] != bodies[1]["request_id"], (
        f"{name}: two separate invokes shared one request id {bodies[0]['request_id']!r}"
    )

    state = lam.get_function_configuration(FunctionName=name)["State"]
    assert state == "Active", f"{name} ended in State={state!r}, expected 'Active'"


if __name__ == "__main__":
    from fidelity_tests_runner import main
    main(run)
